arguments.content:
* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background: #1b1f2a;
  color: #f5f5f5;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#game {
  width: 800px;
  height: 600px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  background: #232838;
  border: 1px solid #3a4258;
  user-select: none;
}

#hud {
  height: 48px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  background: #2c3346;
  font-size: 18px;
  font-weight: 600;
}

#playfield {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  background:
    radial-gradient(circle at 30% 20%, #34405c 0%, transparent 60%),
    radial-gradient(circle at 70% 80%, #34405c 0%, transparent 60%),
    #1e2433;
}

#controls {
  height: 56px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2c3346;
  gap: 16px;
}

button {
  font: inherit;
  font-weight: 700;
  color: #fff;
  background: #4f7cff;
  border: none;
  border-radius: 8px;
  padding: 10px 22px;
  cursor: pointer;
}

button:hover {
  background: #3f6bf0;
}

#start-btn {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-size: 22px;
  padding: 16px 36px;
}

.target {
  position: absolute;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 16px;
  cursor: pointer;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.4);
}

.fruit {
  background: radial-gradient(circle at 35% 30%, #aef5a0, #3bbf3b);
  color: #0a3d0a;
  border: 3px solid #2c8a2c;
}

.bomb {
  background: radial-gradient(circle at 35% 30%, #6b7280, #1f2430);
  color: #ffd34d;
  border: 3px solid #000;
  font-size: 22px;
}

#end-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 12, 20, 0.78);
}

#end-message {
  font-size: 40px;
  font-weight: 800;
  text-align: center;
}

(function () {
  'use strict';

  // ---- Deterministic PRNG (mulberry32) ----
  function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
      a |= 0;
      a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // ---- State ----
  const state = {
    status: 'menu', // menu | playing | won | lost
    score: 0,
    lives: 3,
    sliced: 0,
    remaining: 5,
    bombCount: 0,
  };

  let seed = 1;
  let fruitPositions = [];
  let bombPositions = [];
  let timers = [];
  let events = [];
  let seq = 0;
  let eventEpoch = 0;

  // ---- DOM ----
  const el = {
    score: document.getElementById('score'),
    status: document.getElementById('status'),
    playfield: document.getElementById('playfield'),
    startBtn: document.getElementById('start-btn'),
    fruit: document.getElementById('fruit'),
    bomb: document.getElementById('bomb'),
    restartBtn: document.getElementById('restart-btn'),
    endOverlay: document.getElementById('end-overlay'),
    endMessage: document.getElementById('end-message'),
  };

  function now() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  }

  function clearTimers() {
    for (let i = 0; i < timers.length; i++) clearTimeout(timers[i]);
    timers = [];
  }
  function later(fn, ms) {
    const id = setTimeout(fn, ms);
    timers.push(id);
    return id;
  }

  function emit(type, payload) {
    seq += 1;
    const ev = { seq: seq, tick: now(), type: type, payload: payload || {} };
    events.push(ev);
    return ev;
  }

  function place(node, pos) {
    node.style.left = pos.x + 'px';
    node.style.top = pos.y + 'px';
  }

  // Build a fixed layout from the current seed.
  function buildSchedule() {
    const rng = mulberry32(seed);
    fruitPositions = [];
    bombPositions = [];
    // Five fruit slots (center band) — deterministic per seed.
    for (let i = 0; i < 5; i++) {
      fruitPositions.push({
        x: 250 + Math.floor(rng() * 300),
        y: 180 + Math.floor(rng() * 240),
      });
    }
    // Bomb slots (top-left corner band) — deterministic per seed.
    for (let i = 0; i < 8; i++) {
      bombPositions.push({
        x: 40 + Math.floor(rng() * 110),
        y: 40 + Math.floor(rng() * 110),
      });
    }
  }

  function render() {
    el.score.textContent =
      'Score ' + state.score + ' / 50 (sliced ' + state.sliced + ', left ' + state.remaining + ')';
    const map = { menu: 'Menu', playing: 'Playing', won: 'Won', lost: 'Lost' };
    el.status.textContent = map[state.status] || state.status;
    el.startBtn.hidden = state.status !== 'menu';

    if (state.status === 'won' || state.status === 'lost') {
      el.endOverlay.hidden = false;
      el.endMessage.textContent =
        state.status === 'won' ? 'You Win! Final Score ' + state.score : 'Game Over';
    } else {
      el.endOverlay.hidden = true;
    }
  }

  function showFruit() {
    if (state.status !== 'playing') return;
    if (state.sliced >= 5) return;
    const pos = fruitPositions[state.sliced] || { x: 355, y: 255 };
    place(el.fruit, pos);
    el.fruit.hidden = false;
  }

  function showBomb() {
    if (state.status !== 'playing') return;
    const idx = state.bombCount % bombPositions.length;
    place(el.bomb, bombPositions[idx]);
    el.bomb.hidden = false;
  }

  // ---- Core transitions ----

  // Returns to the menu state. Shared by RESTART control and window.reset().
  function doReset(newSeed) {
    if (typeof newSeed === 'number') seed = newSeed >>> 0;
    clearTimers();
    el.fruit.hidden = true;
    el.bomb.hidden = true;
    state.status = 'menu';
    state.score = 0;
    state.lives = 3;
    state.sliced = 0;
    state.remaining = 5;
    state.bombCount = 0;
    buildSchedule();
    eventEpoch += 1;
    seq = 0;
    events = [];
    emit('game_reset', {});
    render();
  }

  function startGame() {
    if (state.status !== 'menu') return;
    state.status = 'playing';
    el.fruit.hidden = true;
    el.bomb.hidden = true;
    emit('game_started', {});
    showFruit();
    showBomb();
    render();
  }

  function sliceFruit() {
    if (state.status !== 'playing') return;
    if (el.fruit.hidden) return;
    state.score += 10;
    state.sliced += 1;
    state.remaining = Math.max(0, state.remaining - 1);
    emit('fruit_sliced', {
      score: state.score,
      sliced: state.sliced,
      remaining: state.remaining,
    });
    el.fruit.hidden = true;
    if (state.sliced >= 5) {
      state.status = 'won';
      emit('game_won', { score: state.score });
      el.bomb.hidden = true;
      render();
      return;
    }
    showFruit();
    render();
  }

  function hitBomb() {
    if (state.status !== 'playing') return;
    if (el.bomb.hidden) return;
    state.lives = Math.max(0, state.lives - 1);
    emit('bomb_hit', { lives: state.lives });
    el.bomb.hidden = true;
    state.bombCount += 1;
    if (state.lives <= 0) {
      state.status = 'lost';
      emit('game_lost', { lives: state.lives });
      el.fruit.hidden = true;
      render();
      return;
    }
    showBomb();
    render();
  }

  // ---- Real input only ----
  el.startBtn.addEventListener('click', startGame);
  el.restartBtn.addEventListener('click', function () { doReset(seed); });
  el.fruit.addEventListener('click', sliceFruit);
  el.bomb.addEventListener('click', hitBomb);

  // Touch support: preventDefault stops the synthetic click to avoid double firing.
  el.fruit.addEventListener('touchstart', function (e) { e.preventDefault(); sliceFruit(); }, { passive: false });
  el.bomb.addEventListener('touchstart', function (e) { e.preventDefault(); hitBomb(); }, { passive: false });

  // ---- Read-only observation bridge ----
  window.__GAMETESTLAB__ = {
    protocol: 'gametestlab/2',
    isReady: function () { return true; },
    reset: function (opts) {
      const s = opts && typeof opts.seed === 'number' ? opts.seed : seed;
      doReset(s);
    },
    observe: function () {
      return {
        tick: now(),
        status: state.status,
        state: {
          status: state.status,
          score: state.score,
          lives: state.lives,
          sliced: state.sliced,
          remaining: state.remaining,
        },
        event_epoch: eventEpoch,
        latest_event_seq: seq,
      };
    },
    getEvents: function (opts) {
      const after = opts && typeof opts.afterSeq === 'number' ? opts.afterSeq : 0;
      return events.filter(function (e) { return e.seq > after; });
    },
  };

  // ---- Init (no events emitted on first load) ----
  buildSchedule();
  render();
})();

{
  "schema_version": "gametestlab.game-manifest.v3",
  "entry_path": "index.html",
  "surface": "dom",
  "viewport": { "width": 800, "height": 600 },
  "controls": [
    {
      "action_id": "START",
      "actor": "primary",
      "device": "touch",
      "key_event": "tap",
      "selector": "#start-btn",
      "description": "开始游戏"
    },
    {
      "action_id": "SLICE",
      "actor": "primary",
      "device": "touch",
      "key_event": "tap",
      "selector": "#fruit",
      "description": "切中水果"
    },
    {
      "action_id": "BOMB",
      "actor": "primary",
      "device": "touch",
      "key_event": "tap",
      "selector": "#bomb",
      "description": "碰到炸弹"
    },
    {
      "action_id": "RESTART",
      "actor": "primary",
      "device": "touch",
      "key_event": "tap",
      "selector": "#restart-btn",
      "description": "重新开始"
    }
  ],
  "hud_selectors": {
    "score": "[data-testid=\"score\"]",
    "status": "[data-testid=\"status\"]"
  },
  "state_schema": {
    "fields": {
      "status": { "type": "string", "description": "当前状态" },
      "score": { "type": "integer", "description": "分数" },
      "lives": { "type": "integer", "description": "剩余生命" },
      "sliced": { "type": "integer", "description": "已切中水果数" },
      "remaining": { "type": "integer", "description": "剩余水果数" }
    },
    "required": ["status", "score", "lives", "sliced", "remaining"]
  },
  "event_schema": [
    {
      "type": "game_started",
      "description": "游戏开始",
      "payload_fields": {}
    },
    {
      "type": "fruit_sliced",
      "description": "切中水果",
      "payload_fields": {
        "score": { "type": "integer", "description": "当前分数" },
        "sliced": { "type": "integer", "description": "已切中水果数" },
        "remaining": { "type": "integer", "description": "剩余水果数" }
      }
    },
    {
      "type": "bomb_hit",
      "description": "碰到炸弹",
      "payload_fields": {
        "lives": { "type": "integer", "description": "剩余生命" }
      }
    },
    {
      "type": "game_won",
      "description": "游戏胜利",
      "payload_fields": {
        "score": { "type": "integer", "description": "最终分数" }
      }
    },
    {
      "type": "game_lost",
      "description": "游戏失败",
      "payload_fields": {
        "lives": { "type": "integer", "description": "剩余生命" }
      }
    },
    {
      "type": "game_reset",
      "description": "回到菜单/重置",
      "payload_fields": {}
    }
  ],
  "bridge": {
    "protocol": "gametestlab/2",
    "evidence_only": true,
    "actions_via_real_input": true
  }
}
